import random
from collections import Counter

from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_step, log_result
from taf.rfrl.procedures.resources.python.test_models.exceptions import \
    RSSIDiffAboveThreshold, DuplicatedRssiValue


@log_input_and_output
def verify_rssi_values(partial_res):
    """
    Verifies RSSI parameter in 5G Uplink/5G Performance Test Page. Validator checks three requirements:

    1. If RSSI value in particular measure does not have absolute difference in value
    in reference to randomly chosen RSSI measure less than 5;

    2. RSSI values should be unique but with many measures it sometimes happens that there are the same
    values. To prevent false negative results of testing, if any of these occurs method will check if there was a
    'stuck' on RSSI values.

    First measure from Partial Results Table is intentionally skipped in validation as it is not important.
    :param partial_res: Partial Results Table
    :type partial_res: dict
    :return: True if partial results pass validation.
    :rtype: Boolean
    :raises ValueError if RSSI Parameter in Cumulative Results Table does not match with RSSI
    parameter value in the newest measure in Partial Results Table
    :raises ValueError when 20% of all measures have the same RSSI value which is very improbable and may suggest LEKA
    controller stuck under the hood, reporting wrong measure values).
    :raises RSSIDiffAboveThreshold if RSSI Parameter in some measure in Partial Results Table in 5G Uplink
    test models is higher than absolute value of 5 in reference to randomly chosen RSSI
    value from this table.
    """

    partial_res_rssi, random_rssi, recent_rssi_measure = _get_validation_parameters(partial_res)
    log_step("Parameters prepared for validation: \n "
             "Partial Results RSSIs: {0} \n"
             "Randomly chosen RSSI: {1} \n"
             "Recent RSSI measure value: {2}.".format(partial_res_rssi, random_rssi, recent_rssi_measure))

    try:
        _verify_uniqueness_in_rssi_values(random_rssi, partial_res_rssi)

    except DuplicatedRssiValue:
        log_step("Some of RSSI values are repeated - deeper validation begins.")
        _verify_if_rssi_is_stuck(partial_res_rssi)

    _check_rssi_diff_threshold_exceedance(random_rssi, partial_res_rssi)

    log_result("Full validation performed, everything is fine!")

    return True


def verify_rssi_values_v2(rssi_values, deviation=3, stuck_threshold=0.2):
    """
    Verifies RSSI parameters. Validator checks two requirements (based on QC NR Uplink test model requirements):
    * RSSI values should be unique but with many measurements the same value can appear
      and to prevent false negative results of testing, method will check if there was a 'stuck' on RSSI values
      if more than 20% of all values will be the same, keyword will fail.
    * Acceptable deviation is ± 3dB.
    Differences between the verify_rssi_values method and the v2 version:
    * The v2 version validates RSSI deviation using a different approach.
      - method does not skip the first measurement in the list.
      - each RSSI value is compared with all other measurements; the absolute value of the difference must not exceed the deviation.

    :param rssi_values: List of RSSI values.
    :type rssi_values: list[float]
    :param deviation: Acceptable rssi deviation, default is 3dB.
    :type deviation: int
    :param stuck_threshold: Threshold for stuck detection, default is 20%.
    :type stuck_threshold: float
    """
    random_rssi = random.choice(rssi_values)

    try:
        _verify_uniqueness_in_rssi_values(random_rssi, rssi_values)

    except DuplicatedRssiValue:
        log_step("Some of RSSI values are repeated - deeper validation begins.")
        _verify_if_rssi_is_stuck(rssi_values, stuck_threshold)

    _verify_rssi_deviation(rssi_values, deviation)


@log_input_and_output
def _get_validation_parameters(partial_res_table):
    """
    Get parameters needed for RSSI validation.

    :param partial_res_table: Partial Results Table.
    :type partial_res_table: dict
    :return: Following variables are returned - RSSI value from cumulative results table, list of RSSI values from
             all measures in partial results table, randomly chosen RSSI from partial results table measures and
             recent rssi measure in partial results table.
    :rtype: tuple
    """

    partial_res_rssi = partial_res_table['RSSI'][:-1]
    recent_rssi_measure = partial_res_rssi[0]

    random_rssi = random.choice(partial_res_rssi)
    partial_res_rssi.remove(random_rssi)
    random_rssi = float(random_rssi)

    return partial_res_rssi, random_rssi, recent_rssi_measure


@log_input_and_output
def _verify_uniqueness_in_rssi_values(random_rssi, part_res_rssi):
    """
    Verifies if all RSSI values in Partial Results Table are unique as they should be.

    :param random_rssi: Randomly chosen RSSI from Partial Results Table. - this value should not be in
           Partial Results Table (random chosen RSSI should pop out of Partial Results Table).
    :type random_rssi: str/float
    :param part_res_rssi: RSSI values from Partial Results Table.
    :type part_res_rssi: list
    :raises ValueError if RSSI values will not be unique.
    """
    log_step("Verification of results uniqueness begins.")
    unique_part_res_rssi = set(part_res_rssi)

    if (len(unique_part_res_rssi) != len(part_res_rssi)) or (str(random_rssi) in unique_part_res_rssi):
        raise DuplicatedRssiValue("In partial results table exists the same RSSI for two different measures!")

    log_result("Validation succeeded - all RSSI values in Partial Results Table are unique.")


@log_input_and_output
def _verify_if_rssi_is_stuck(partial_res_rssi, stuck_threshold=0.2):
    """
    Verifies if RSSI values are stuck in list of values from Partial Results Table.

    :param partial_res_rssi: RSSI values from Partial Results Table
    :type partial_res_rssi: list
    :param stuck_threshold: Threshold for stuck detection, default is 20%.
    :type stuck_threshold: float
    :raises ValueError if more than 20% of all values will be the same.

    """
    log_step("Number of RSSI values in provided list: {0}".format(len(partial_res_rssi)))
    counted_values = Counter(partial_res_rssi)
    most_common_value, number_of_occurrences = counted_values.most_common(1)[0]
    log_result("Most common value in list: {0}, number of its' occurrences: {1}".format(most_common_value,
                                                                                        number_of_occurrences))

    if int(number_of_occurrences) > stuck_threshold * len(partial_res_rssi):
        log_result("Number of occurrences of {0} value is {1} counts above threshold!".
                   format(most_common_value, int(number_of_occurrences) - stuck_threshold * len(partial_res_rssi)))
        raise ValueError("There might be a stuck on LEKA controller as {0} occurences of "
                         "{1} RSSI value were detected".format(number_of_occurrences, most_common_value))

    log_result("No potential stucks or detected problems on controller")


@log_input_and_output
def _check_rssi_diff_threshold_exceedance(random_rssi, part_res_rssi):
    """
    Checks if any of RSSI value from all measures provided via part_res_rssi list exceeds threshold.

    :param random_rssi: Randomly chosen RSSI from Partial Results Table.
    :type random_rssi: float
    :param part_res_rssi: RSSI values from Partial Results Table
    :type part_res_rssi: list
    :raise RSSIDiffAboveThreshold if any of rssi value has delta bigger than 5 with randomly chosen RSSI provided via
           random_rssi argument.
    """
    log_step("Threshold validation begins - looking for RSSI values that exceeds threshold provided in docs.")

    for measure in part_res_rssi:
        delta = abs(random_rssi - float(measure))

        if delta > 5:
            raise RSSIDiffAboveThreshold("Difference is above the threshold of 5. \n measure RSSI: {0}."
                                         " \n randomly chosen RSSI: {1}".format(float(measure), random_rssi))

    log_result("No outliers detected")


@log_input_and_output
def _verify_rssi_deviation(rssi_values, max_deviation):
    """
    Verifies RSSI deviation.

    :param rssi_values: List of RSSI values.
    :type rssi_values: list[float]
    :param max_deviation: Acceptable rssi deviation.
    :type max_deviation: int
    :raises RSSIDiffAboveThreshold if the deviation between the maximum RSSI value and the minimum RSSI value exceeds the expected threshold.
    """
    if abs(max(rssi_values) - min(rssi_values)) > max_deviation:
        raise RSSIDiffAboveThreshold(f"RSSI value {max(rssi_values)} compared to {min(rssi_values)} deviates "
                                     f"by more than {max_deviation}dB.")

    log_result("RSSI values are within the acceptable deviation.")
